SELECT CAST(ROUND((
    (SELECT overall_rating FROM v_Player_Attributes WHERE player_fifa_api_id = 218353 AND date = '2013-07-12'
) - (SELECT overall_rating FROM v_Player_Attributes WHERE player_fifa_api_id = 67950 AND date = '2013-07-12'
)) AS REAL) / (
    SELECT overall_rating FROM v_Player_Attributes WHERE player_fifa_api_id = 218353 AND date = '2013-07-12'
) * 100.0
FROM v_Team_Attributes t
JOIN v_Player_Attributes p ON t.team_fifa_api_id = p.player_fifa_api_id

